    if(had) window.dispatchEvent(new MouseEvent('mouseup',{button:0}));
    else cv.dispatchEvent(new MouseEvent('mousedown',{button:0}));
  }catch(_pe){}
  if(!had&&G.drag) G.drag.pad=1;
  return true;
}
